"""VR rule coverage report (T-01). Regenerated by `python -m rq1.schema.coverage`, never hand-edited."""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from rq1.fixtures.vr_cases import CASES

from . import registry

ACTIVE = [*range(1, 6), *range(10, 19), 20, 21, 30, 31, 32, 34, 40, 41, *range(50, 56), *range(60, 63), 70, 71]


@dataclass(frozen=True)
class RuleStatus:
    status: str
    note: str


def vr_status() -> dict[str, RuleStatus]:
    cased = {c.rule: c for c in CASES}
    report: dict[str, RuleStatus] = {}
    for number in ACTIVE:
        rule = f"VR-E-{number:03d}"
        report[rule] = RuleStatus("implemented", cased[rule].citation) if rule in cased else RuleStatus("missing", "No fixture.")
    return report


def render() -> str:
    status = vr_status()
    implemented = sum(1 for x in status.values() if x.status == "implemented")
    lines = ["# T-01 VR failing-fixture coverage", "", "Generated by `python -m rq1.schema.coverage`. Do not edit by hand.", "",
             f"Contract E-1.2.3. Active VR rules: {len(status)}. Implemented with one passing and one failing fixture: {implemented}.", "",
             "| Rule | Status | Note |", "|---|---|---|"]
    lines += [f"| {r} | {s.status} | {s.note} |" for r, s in sorted(status.items())]
    tables = registry.TABLES.values()
    inferred = sorted(t.name for t in tables if t.types_inferred)
    provisional = sorted(f"{t.name}.{f.name}" for t in tables for f in t.fields if f.provisional)
    lines += ["", "## Schema items settled by Agent Resolutions", "", f"Tables registered: {len(registry.TABLES)}.", "",
              f"Tables with column types chosen under AR-2 ({len(inferred)}): {', '.join(inferred)}.", "",
              f"Columns added or named under AR-1, AR-5, AR-6 or AR-9 ({len(provisional)}): {', '.join(provisional)}.", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    target = Path("reports/T-01_vr_coverage.md")
    target.parent.mkdir(exist_ok=True)
    target.write_text(render(), encoding="utf-8")
    print(target)
